format_price_function.old:
def format_price(price, is_isaco=False):
    if price is None or price == 0:
        return "0 ریال"
    full_rial = float(price)
    if is_isaco:
        full_rial = full_rial * 1.10
    return f"{full_rial:,.0f} ریال"

